files.content:
.icon{
  width:var(--icon-sm);
  height:var(--icon-sm);
  flex:none;
  fill:none;
  stroke:currentColor;
  stroke-width:1.5;
  stroke-linecap:round;
  stroke-linejoin:round;
  vertical-align:middle;
}
.icon-xs{
  width:var(--icon-xs);
  height:var(--icon-xs);
}
.icon-md{
  width:var(--icon-md);
  height:var(--icon-md);
}
.icon-lg{
  width:var(--icon-lg);
  height:var(--icon-lg);
}
.icon-muted{
  color:var(--obsidian-300);
}
.icon-fill{
  fill:currentColor;
  stroke-width:var(--bw-1);
}
